$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='coach'||!isset($user['id'])){http_response_code(403);exit('Diese Moduleinstellungen sind nur für Coaches verfügbar.');}
$db=coachingDatabase();$coach=(int)$user['id'];$defs=coachingModuleDefinitions();$settings=coachingCoachModuleSettings($db,$coach);$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}$error='';$notice=isset($_GET['saved'])?'Deine Modulauswahl wurde gespeichert.':'';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}$cols=array_map(static fn(array $m):string=>$m['column'],$defs);$values=[];foreach($defs as $key=>$def)$values[$def['column']]=isset($_POST[$key])?1:0;$binds=implode(', ',array_map(static fn(string $c):string=>':'.$c,$cols));$updates=implode(', ',array_map(static fn(string $c):string=>$c.' = VALUES('.$c.')',$cols));try{$q=$db->prepare('INSERT INTO coaching_coach_moduleeinstellungen (coach_benutzer_id, '.implode(', ',$cols).') VALUES (:coach, '.$binds.') ON DUPLICATE KEY UPDATE '.$updates);$q->execute(['coach'=>$coach]+$values);header('Location: module-settings.php?saved=1');exit;}catch(Throwable $e){error_log('Coach module settings save failed: '.$e->getMessage());foreach($defs as $key=>$_)$settings[$key]=isset($_POST[$key])?1:0;$error='Einstellungen konnten nicht gespeichert werden. Bitte Migration 023 importieren und Tabellenrechte prüfen.';}}
